word('midi','fr:midi:noon','midi','полдень (двенадцать часов дня)','миди́',2,ex('Le rendez-vous est à midi.','Встреча в полдень.','лё ра(н)дэ ву э а миди́'),['Полночь','Полдень','Девять утра'],1,'Нужно назначить встречу в полдень.',[('Rendez-vous à neuf heures.','ра(н)дэ ву а нё вё́р'),('Rendez-vous à dix heures.','ра(н)дэ ву а ди зё́р'),('Rendez-vous à midi.','ра(н)дэ ву а миди́')],2)
word('et-quart','fr:et-quart:quarter-past-time','et quart','пятнадцать минут после названного часа','э ка́р',2,ex('Le rendez-vous est à neuf heures et quart.','Встреча в девять пятнадцать.','лё ра(н)дэ ву э а нё вёр э ка́р'),['Пятнадцать минут после часа','Тридцать минут после часа','Ровно названный час'],0,'Нужна встреча в девять пятнадцать.',[('Rendez-vous à neuf heures et demie.','ра(н)дэ ву а нё вёр э дёми́'),('Rendez-vous à neuf heures et quart.','ра(н)дэ ву а нё вёр э ка́р'),('Rendez-vous à neuf heures.','ра(н)дэ ву а нё вё́р')],1)
word('et-demie','fr:et-demie:half-past-hour','et demie','тридцать минут после названного часа','э дёми́',2,ex('Le rendez-vous est à neuf heures et demie.','Встреча в девять тридцать.','лё ра(н)дэ ву э а нё вёр э дёми́'),['Ровно названный час','Пятнадцать минут после часа','Тридцать минут после часа'],2,'Нужно выбрать девять тридцать.',[('Neuf heures et demie.','нё вёр э дёми́'),('Neuf heures et quart.','нё вёр э ка́р'),('Neuf heures.','нё вё́р')],0)
word('disponible','fr:disponible:available-in-schedule','disponible','свободен по расписанию','диспони́бль',3,ex('Je suis disponible mardi à midi.','Я свободен во вторник в полдень.','жё сюи диспонибль марди а миди́'),['Занят по расписанию','Свободен по расписанию','Опаздывает'],1,'Вы свободны во вторник в полдень. Как сообщить именно об этом?', [('Je suis occupé mardi à midi.','жё сюи окюпэ марди а миди́'),('Je suis disponible mardi à midi.','жё сюи диспонибль марди а миди́'),('Je suis disponible mercredi à midi.','жё сюи диспонибль мэркрёди а миди́')],1)
