word('on-peut-se-retrouver','fr:on-peut-se-retrouver:meeting-proposal','on peut se retrouver','можем встретиться (рамка предложения)','о(н) пё сё рётрувэ́',4,ex('On peut se retrouver au café à midi ?','Можем встретиться в кафе в полдень?','о(н) пё сё рётрувэ о кафэ а миди́'),['Сообщает об оплате','Просит ключ','Предлагает встретиться'],2,'Нужно предложить встретиться в парке в полдень.',[('On peut se retrouver au parc à midi ?','о(н) пё сё рётрувэ о парк а миди́'),('Je paie par carte.','жё пэ пар ка́рт'),('Où est la gare ?','у э ла га́р')],0)
word('daccord','fr:daccord:agreement','d’accord','согласен (принятие предложения)','дако́р',4,ex('D’accord, rendez-vous à midi.','Согласен, встречаемся в полдень.','дакор, ра(н)дэ ву а миди́'),['Отказ','Согласие с предложением','Вопрос о месте'],1,'Вы принимаете предложение встретиться в полдень.',[('Non, je suis occupé à midi.','но(н), жё сюи окюпэ а миди́'),('D’accord, rendez-vous à midi.','дакор, ра(н)дэ ву а миди́'),('Où est la gare ?','у э ла га́р')],1)
def cards(ids):return [wc(w) for w in ids]
