order(s,[A],['disponible','mardi','midi'],[],'Соберите «Вы свободны во вторник в полдень?». Начните с изученного вопросительного оборота.',[('Est-ce que','эс кё'),('vous êtes disponible','ву зэт диспони́бль'),('mardi','марди́'),('à midi ?','а миди́')],'Est-ce que vous êtes disponible mardi à midi ?','эс кё ву зэт диспонибль марди а миди́?','Получился вопрос о конкретном свободном времени.','Сначала поставьте начало вопроса, затем обращение с признаком свободен, вторник и полдень.')
page(s,[('Доступность в конкретный момент',['Свободен во вторник в полдень не означает свободен весь вторник. Для ответа сохраняйте день и время вместе.'],[W['disponible']['example'],W['occupe']['example']]),('Спросить собеседника',['Готовый вопрос отличается от ответа о себе. На этом этапе достаточно показанного сочетания без полной таблицы лиц.'],[ex('Est-ce que vous êtes disponible mardi à midi ?','Вы свободны во вторник в полдень?','эс кё ву зэт диспонибль марди а миди́')]),('Два условия',['Подходящий момент должен отвечать и нужному дню, и свободному времени. Доступность в другой день не даёт ответа на вопрос о вторнике.'],[ex('Je suis disponible mercredi à neuf heures.','Я свободен в среду в девять часов.','жё сюи диспонибль мэркрёди а нё вё́р')])])

