 review_targets_for_next_unit=[dict(lexeme_key=W[w]['lexeme_key'],reason=r) for w,r in [('rendez-vous','Сохранить прежний ключ назначенной встречи в следующей теме друзей и досуга.'),('disponible','Вернуть свободное время при согласовании совместного занятия.'),('occupe','Повторить занятость в конкретный момент без вывода о всём дне.'),('on-peut-se-retrouver','Повторить готовое предложение встречи до расширения досуга.'),('daccord','Повторить принятие предложения отдельно от вопроса о доступности.'),('midi','Вернуть полдень как удобную точку времени.'),('et-quart','Повторить пятнадцать минут после часа.'),('et-demie','Повторить тридцать минут после часа, не смешивая с четвертью.'),('juin','Вернуть новый месяц в короткой календарной записи.'),('juillet','Сохранить различие июня и июля.')]],
